import{_ as a,o as e,c as o,a5 as i}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"選項","description":"","frontmatter":{"title":"選項","order":7},"headers":[],"relativePath":"tc/latest/tutorial/script/choice.md","filePath":"tc/latest/tutorial/script/choice.md","lastUpdated":1788455378000}'),s={name:"tc/latest/tutorial/script/choice.md"};function c(d,t,l,r,n,h){return e(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="選項跳轉" tabindex="-1">選項跳轉 <a class="header-anchor" href="#選項跳轉" aria-label="Permalink to &quot;選項跳轉&quot;">​</a></h1><h2 id="功能概述" tabindex="-1">功能概述 <a class="header-anchor" href="#功能概述" aria-label="Permalink to &quot;功能概述&quot;">​</a></h2><p>此功能需與<strong>分支功能</strong>搭配使用，核心作用是在互動選項標籤中設定跳轉邏輯。點擊對應選項後，可直接跳轉到指定分支節點。每個 <code>choice</code> 語句建立一個選項，多個相鄰的 <code>choice</code> 行會被合併為一個選項組，互動時會同時展示。</p><h2 id="語法規範" tabindex="-1">語法規範 <a class="header-anchor" href="#語法規範" aria-label="Permalink to &quot;語法規範&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;選項內容&quot; -&gt; 分支名稱</span></span></code></pre></div><table tabindex="0"><thead><tr><th>參數</th><th>必填</th><th>範例</th><th>說明</th></tr></thead><tbody><tr><td>選項內容</td><td>是</td><td>&quot;選擇咖啡&quot;</td><td>互動時展示的選項文字內容</td></tr><tr><td>分支名稱</td><td>是</td><td>coffee_choice</td><td>需跳轉的目標分支唯一識別符</td></tr></tbody></table><h2 id="使用範例" tabindex="-1">使用範例 <a class="header-anchor" href="#使用範例" aria-label="Permalink to &quot;使用範例&quot;">​</a></h2><p>每個選項單獨一行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;Green tea&quot; -&gt; green_tea</span></span>
<span class="line"><span>choice &quot;Black tea&quot; -&gt; black_tea</span></span></code></pre></div><h2 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h2><ol><li>分支名稱需與專案中定義的分支識別符完全一致，區分大小寫，且不可包含空格、特殊符號；</li><li>選項內容需用英文雙引號包裹，支援常規文字字元；</li><li><code>-&gt;</code> 是選項與分支名稱之間的分隔符，不可省略；</li></ol>`,11)])])}const b=a(s,[["render",c]]);export{u as __pageData,b as default};
